jsonTools.init:
function init(eli) {
  if (!eli || !eli.ui || !eli.storage) return;
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded.business_continuity;
  if (!bundle) return;

  // 2026-05-23: code lives on Colgate's GitHub org.
  var CODE_HOME = {
    org: "Colgate's GitHub org — https://github.com/colpal",
    kernelRepo: "https://github.com/colpal (kernel source + tool source folders + build scripts; the kernel itself runs as a Script Lab snippet that gets pasted in from the deploy file)",
    cdnRepo: "https://github.com/colpal (tool bundles + manifest + admin overrides served via jsdelivr)",
    contactBackup: "Find the ELI repos under Colgate's GitHub org. If access isn't already provisioned to your account, contact whoever administers Colgate's GitHub org.",
  };

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _toast(msg, kind) {
    if (typeof showToast === "function") showToast(msg, kind || "info");
  }

  // ─── Section 1: How ELI Works ────────────────────────────────────
  function _renderHowItWorks() {
    return '' +
      '<div class="_bc_section">' +
        '<h2>How ELI Works (the 5-minute version)</h2>' +
        '<p><b>ELI is an Office.js add-in for Microsoft Word</b>, currently shipped as a Script Lab snippet. ' +
        'Long-term it can be packaged as a real Office Add-in or ported to Google Docs.</p>' +
        '<h3>Architecture: kernel + tools</h3>' +
        '<ul>' +
          '<li><b>The kernel</b> is a single JavaScript file (~11k lines) that runs once when the taskpane opens. ' +
          'It boots IndexedDB, the registry, three "providers" (host / ai / storage), the UI primitives, and the FSM. ' +
          'Kernel is pasted into a Script Lab snippet today; copy/paste deploy.</li>' +
          '<li><b>Tools</b> are JSON bundles loaded into IndexedDB on demand. ' +
          'Each tool is self-contained code that talks to the kernel through the providers — never directly to Word, ' +
          'never directly to AI, never directly to IndexedDB. ' +
          'New tools ship via a CDN (jsdelivr backed by GitHub) and auto-update on next reload.</li>' +
        '</ul>' +
        '<h3>Where data lives</h3>' +
        '<table class="_bc_table"><thead><tr><th>Location</th><th>What\'s there</th></tr></thead><tbody>' +
          '<tr><td><b>localStorage</b> (per-browser, per-user)</td><td>' +
            'Small user prefs: AI model choice, theme, dashboard pin order, ' +
            'encrypted API key, GitHub PAT, admin password, language. ' +
            'Inherited from v2; intentionally not migrated to IDB. ' +
            '<b>API key and other credentials NEVER leave the user\'s machine</b> — ' +
            'no code path sends them to GitHub, the CDN, or telemetry. ' +
            'They\'re only sent to Google\'s AI endpoint when the user makes an AI call.' +
          '</td></tr>' +
          '<tr><td><b>IndexedDB</b> (per-browser, per-user)</td><td>' +
            'Tool bundles, BD templates, clause library, manifest cache, ' +
            'usage stats, activity feed, wrongness captures, applied-override markers. ' +
            'Anything heavy or shared between tools.' +
          '</td></tr>' +
          '<tr><td><b>CDN repo</b> (' + _esc(CODE_HOME.cdnRepo) + ')</td><td>' +
            '<code>tools-manifest-v3.json</code> (catalog of tools), one JSON per tool bundle, ' +
            '<code>admin-overrides.json</code> (push commands to user installs), ' +
            '<code>usage/&lt;userKey&gt;.json</code> (anonymized per-user telemetry digests), ' +
            '<code>fleet-identity.enc.json</code> (encrypted email→UUID lookup).' +
          '</td></tr>' +
          '<tr><td><b>Code repo</b> (' + _esc(CODE_HOME.kernelRepo) + ')</td><td>' +
            'Kernel source, tool source folders, build scripts, this app. ' +
            'Source of truth for everything except user state.' +
          '</td></tr>' +
          '<tr><td><b>Google AI (Gemini)</b></td><td>' +
            'Where AI prompts are sent. Each user supplies their own API key, stored encrypted in their own localStorage. ' +
            'The API key is only ever used to authenticate calls to <code>generativelanguage.googleapis.com</code> — ' +
            'it is never logged, never copied to the CDN, never included in telemetry.' +
          '</td></tr>' +
        '</tbody></table>' +
        '<h3>Credentials — single point of clarity</h3>' +
        '<p><b>Every credential ELI uses (Gemini API key, GitHub PAT, admin password, library cipher) is stored ONLY in the user\'s own browser localStorage on their own machine.</b> ' +
        'None of these are uploaded to GitHub, none appear in telemetry, none are visible to other users, and none are visible to the admin without that user explicitly providing them. ' +
        'When admin pushes new sensitive values to a user (via Admin Fleet → encrypted push), the value travels as ciphertext through admin-overrides.json and is decrypted only on the target user\'s machine.</p>' +
        '<h3>The provider rule (most important architectural rule)</h3>' +
        '<p>Tools <b>never</b> call <code>Word.run</code>, <code>fetch</code>, or <code>indexedDB</code> directly. ' +
        'They go through <code>eli.host</code> (Word), <code>eli.ai</code> (Gemini), and <code>eli.storage</code> (IndexedDB). ' +
        'This makes the architecture portable (Google Docs later means rewriting eli.host, not 50 tools), ' +
        'testable (engines are pure functions), and safe (PII protection lives in one place).</p>' +
        '<h3>Update flow</h3>' +
        '<ol>' +
          '<li>Edit a tool in <code>tools/&lt;name&gt;/</code></li>' +
          '<li>Run <code>node scripts/build_tool.js &lt;name&gt;</code> — outputs to <code>bundles/&lt;name&gt;.json</code></li>' +
          '<li>Run <code>node scripts/release_tools.js</code> — copies to the CDN repo, commits, pushes</li>' +
          '<li>Users\' installs auto-poll the manifest every 30 min; they get the new version on next reload</li>' +
        '</ol>' +
        '<p>For kernel changes: edit <code>taskpane_v3.js</code>, run <code>node scripts/strip_for_deploy.js</code>, ' +
        'paste the resulting <code>taskpane_v3.deploy.js</code> into the Script Lab snippet. ' +
        'No automatic kernel push — each install needs the new snippet pasted manually.</p>' +
      '</div>';
  }

  // ─── Section 2: Continue ELI ─────────────────────────────────────
  function _renderOption1() {
    return '' +
      '<div class="_bc_section">' +
        '<h2>Option 1 — Keep ELI running</h2>' +
        '<p>If you want to continue ELI, here is what you inherit and what to do first.</p>' +
        '<h3>The code lives at:</h3>' +
        '<p><b>' + _esc(CODE_HOME.org) + '</b><br>' +
          'Code repo: <code>' + _esc(CODE_HOME.kernelRepo) + '</code><br>' +
          'CDN repo: <code>' + _esc(CODE_HOME.cdnRepo) + '</code></p>' +
        '<p><b>Action item:</b> ' + _esc(CODE_HOME.contactBackup) + '</p>' +
        '<h3>What to install / configure</h3>' +
        '<ul>' +
          '<li><b>Node.js</b> (any recent LTS) — for the build scripts</li>' +
          '<li><b>Git</b> — for the two repos above</li>' +
          '<li><b>GitHub Personal Access Token</b> with repo write — used by <code>release_tools.js</code> to push to the CDN repo</li>' +
          '<li><b>Microsoft Word + Script Lab add-in</b> — to test the kernel</li>' +
        '</ul>' +
        '<h3>Day-to-day operations</h3>' +
        '<ul>' +
          '<li><b>Ship a tool update</b>: edit <code>tools/&lt;name&gt;/init.js</code>, ' +
            'then <code>node scripts/build_tool.js &lt;name&gt; && node scripts/release_tools.js</code>. ' +
            'Users get it on next reload (or sooner via Tool Manager → Check for Updates).</li>' +
          '<li><b>Push a setting / kill switch / notice to one or all users</b>: ' +
            'open the <b>Admin Fleet</b> tool. Per-user cards have Push setting / Send notice / Pin / Disable / etc. ' +
            'The header has a Broadcast button for fleet-wide messages.</li>' +
          '<li><b>See who\'s using what</b>: Admin Fleet also shows per-user installed tools, ' +
            'pinned tiles, currently-applied overrides (Applied / Pending status).</li>' +
          '<li><b>Ship a kernel update</b>: edit <code>taskpane_v3.js</code>, ' +
            'bump <code>kernelVersion</code> at line ~341, ' +
            '<code>node scripts/strip_for_deploy.js</code>, ' +
            'paste <code>taskpane_v3.deploy.js</code> into your Script Lab snippet. ' +
            '<b>Then ask each colleague to do the same paste</b> — kernel is the only thing that doesn\'t auto-update.</li>' +
        '</ul>' +
        '<h3>Required reading (in the repo)</h3>' +
        '<ul>' +
          '<li><code>CLAUDE.md</code> — architectural rules. Every "why" is documented.</li>' +
          '<li><code>V3_PHASES.md</code> — phased rebuild log + decisions log.</li>' +
          '<li><code>docs/TOOL_MIGRATION.md</code> — how to add a new tool.</li>' +
        '</ul>' +
        '<h3>What\'s the cost of running this?</h3>' +
        '<ul>' +
          '<li><b>GitHub repos</b>: free</li>' +
          '<li><b>jsdelivr CDN</b>: free (just serves the GitHub repo)</li>' +
          '<li><b>Gemini AI</b>: each user pays for their own key. Typical cost: a few cents per user per month at current usage.</li>' +
          '<li><b>Your time</b>: maybe 1-2 hrs/week for tool updates + colleague support if you treat it as a side project. ' +
            'More if you actively develop new features.</li>' +
        '</ul>' +
        '<h3>People to talk to</h3>' +
        '<ul>' +
          '<li><b>Ken Capece</b></li>' +
          '<li><b>Aleks Ozerov</b></li>' +
        '</ul>' +
      '</div>';
  }

  // ─── Section 3: Wind Down + Export ───────────────────────────────
  function _renderOption2() {
    return '' +
      '<div class="_bc_section">' +
        '<h2>Option 2 — Wind ELI down</h2>' +
        '<p>If continuing ELI doesn\'t make sense, you can still preserve the valuable content ' +
        '(BD templates, clause library, playbooks, team guidance) by exporting them to Word documents. ' +
        'After that, users can simply uninstall ELI and keep working with the exported files manually.</p>' +
        '<h3>What\'s worth exporting</h3>' +
        '<ul>' +
          '<li><b>BD templates</b> — pre-baked draft text blocks that Build Draft assembles into contracts. ' +
            'Most of the "institutional knowledge" lives here.</li>' +
          '<li><b>Clause library</b> — preferred / fallback / unacceptable clauses by topic.</li>' +
          '<li><b>Team guidance</b> — clause-specific commentary teammates posted while reviewing redlines.</li>' +
          '<li><b>Playbooks</b> — agreement-type-specific rules for review_redlines.</li>' +
        '</ul>' +
        '<h3>Export buttons</h3>' +
        '<p>Each button opens a new Word document and inserts the data as formatted text. ' +
        'You can edit / save / share like any other doc.</p>' +
        '<div class="_bc_export_grid">' +
          '<button class="_bc_btn _bc_btn_primary" data-bc-act="export-bd-templates">' +
            '📄 Export a BD template (pick one)</button>' +
          '<button class="_bc_btn" data-bc-act="export-clauses">' +
            '📚 Export clause library to Word</button>' +
          '<button class="_bc_btn" data-bc-act="export-team-guidance">' +
            '💬 Export team guidance to Word</button>' +
          '<button class="_bc_btn" data-bc-act="export-playbooks">' +
            '🎯 Export playbooks to Word</button>' +
          '<button class="_bc_btn _bc_btn_subtle" data-bc-act="export-all-json">' +
            '🗂️ Dump ALL stores as JSON (backup)</button>' +
        '</div>' +
        '<h3>After exporting</h3>' +
        '<ol>' +
          '<li>Save each Word document somewhere safe (SharePoint, OneDrive, etc.)</li>' +
          '<li>Tell users to uninstall the Script Lab snippet or remove the add-in</li>' +
          '<li>Optionally archive the GitHub repos as a snapshot</li>' +
          '<li>If you change your mind later, the CDN-served bundles will keep working as long as the GitHub repos exist</li>' +
        '</ol>' +
        '<h3>What you can\'t (and shouldn\'t) export</h3>' +
        '<ul>' +
          '<li>Per-user activity history / stats (anonymized; not very portable)</li>' +
          '<li><b>Credentials</b> (Gemini API key, GitHub PAT, admin password, library cipher) — ' +
            'these are stored ONLY on each user\'s local machine. ' +
            'Nothing here uploads them to GitHub or anywhere else. ' +
            'When ELI is wound down, each user keeps their own credentials locally; nothing for the org to retrieve.</li>' +
          '<li>UI preferences (theme, pins) — local to each user</li>' +
        '</ul>' +
      '</div>';
  }

  // ─── Export implementations ──────────────────────────────────────
  // Each export reads the relevant IDB store, formats as paragraphs, then
  // pastes into a NEW Word document via eli.host. Doc opens in Word so the
  // user can immediately save / share.
  function _writeDocBlocks(title, paragraphs) {
    // Build a single text payload and paste into the current document.
    // Adding a new Word doc programmatically requires Word.Application
    // scripting which Office.js doesn't expose; instead we insert at the
    // cursor of the CURRENT doc, with a header so the user can see what's
    // what and either keep or paste-elsewhere.
    if (typeof eli.host === "undefined" || typeof eli.host.runRaw !== "function") {
      _toast("Cannot insert into Word — host provider unavailable", "err");
      return Promise.reject(new Error("no host provider"));
    }
    return eli.host.runRaw("business_continuity.export", function (context) {
      var body = context.document.body;
      var divider = body.insertParagraph(
        "\n══════════════════════════════════════════\n" + title + "\nExported " + new Date().toLocaleString() +
        "\n══════════════════════════════════════════\n",
        "End"
      );
      divider.font.bold = true;
      divider.font.size = 14;
      paragraphs.forEach(function (p) {
        if (typeof p === "string") {
          body.insertParagraph(p, "End");
        } else if (p && p.heading) {
          var h = body.insertParagraph(p.heading, "End");
          h.font.bold = true;
          h.font.size = 12;
          if (p.body) body.insertParagraph(p.body, "End");
        }
      });
      return context.sync();
    });
  }

  // Decompress a single BD template row matching build_draft's actual
  // wire format ([init.js:92] _bdMaybeCompress):
  //   _z: 1 flag + content: Uint8Array (deflated UTF-8)
  // NOT base64, NOT gzip — pako.deflate / pako.inflate, raw bytes.
  // Uncompressed rows: content is a string already.
  function _bdDecompress(r) {
    if (!r) return r;
    if (!r._z) return r;
    if (typeof window.pako === "undefined") {
      return Object.assign({}, r, {
        content: "[ERROR: template is compressed but pako library is not loaded. Add https://cdn.jsdelivr.net/npm/pako@2.1.0/dist/pako.min.js to Script Lab Libraries and reload.]",
        _z: 0,
      });
    }
    try {
      var bytes = r.content; // Uint8Array of deflated UTF-8
      var utf8 = window.pako.inflate(bytes);
      var text = new TextDecoder().decode(utf8);
      return Object.assign({}, r, { content: text, _z: 0 });
    } catch (e) {
      return Object.assign({}, r, {
        content: "[ERROR decoding compressed template: " + (e && e.message || e) + "]",
        _z: 0,
      });
    }
  }

  // 2026-05-23 (revised): match admin_template_studio's working pattern.
  // BD templates are stored as full <pkg:package> envelopes — Word.js
  // only accepts those at InsertLocation.replace, NOT End/After/Before
  // ("GeneralException" otherwise). admin_template_studio uses Replace.
  // We do the same here. The current doc gets wiped — caller must
  // confirm with user first via _confirmReplaceThenExport.
  function _writeBdTemplateToDoc(label, metaLines, content) {
    if (typeof eli.host === "undefined" || typeof eli.host.runRaw !== "function") {
      return Promise.reject(new Error("no host provider"));
    }
    // 2026-05-23: same preprocessing build_draft does at [init.js:1381].
    // Word's OOXML parser is stricter than XMLSerializer's output —
    // requires CRLF separators between PIs and before <pkg:package>.
    // Without this, glued-together preambles fail with GeneralException.
    function _normalizeOoxml(ooxml) {
      return String(ooxml || "")
        .replace(/\?>\s*<\?/g, "?>\r\n<?")
        .replace(/\?>\s*<pkg:package/g, "?>\r\n<pkg:package");
    }
    return eli.host.runRaw("business_continuity.export_template", function (context) {
      var body = context.document.body;
      // OOXML branch — full package, replace the doc.
      var looksLikeOoxml = /<pkg:package|<w:document|<w:body/.test(content || "");
      if (looksLikeOoxml && content && content.trim()) {
        body.insertOoxml(_normalizeOoxml(content), Word.InsertLocation.replace);
      } else if (content && content.trim()) {
        // Plain-text template — clear and rewrite as paragraphs.
        body.clear();
        content.split(/\r?\n/).forEach(function (line) {
          body.insertParagraph(line, Word.InsertLocation.end);
        });
      } else {
        body.clear();
        body.insertParagraph("(This template has no content.)", Word.InsertLocation.end);
      }
      // Prepend the export header AFTER the content lands. insertParagraph
      // at Start prepends — gives the user a small "exported" label above
      // the template content without disturbing the template's own
      // formatting.
      var hdrLines = [
        "ELI — BD Template: " + label,
        "Exported " + new Date().toLocaleString(),
      ];
      (metaLines || []).reverse().forEach(function (line) {
        body.insertParagraph(line, Word.InsertLocation.start);
      });
      hdrLines.reverse().forEach(function (line) {
        var p = body.insertParagraph(line, Word.InsertLocation.start);
        p.font.bold = true;
      });
      return context.sync();
    });
  }

  function _exportBdTemplates() {
    _toast("⏳ Reading BD templates…", "info");
    return eli.storage.getAll("bd_templates").then(function (rows) {
      if (!rows || !rows.length) {
        _toast("No BD templates found", "warn");
        return;
      }
      var templates = rows.map(_bdDecompress);
      // Sort by display name so the picker is predictable.
      templates.sort(function (a, b) {
        var an = (a.name || a.title || a.id || "").toLowerCase();
        var bn = (b.name || b.title || b.id || "").toLowerCase();
        return an < bn ? -1 : an > bn ? 1 : 0;
      });
      _showBdTemplatePicker(templates);
    }).catch(function (err) {
      _toast("Read failed: " + (err && err.message || "unknown"), "err");
    });
  }

  function _showBdTemplatePicker(templates) {
    if (typeof showEliDialog !== "function") {
      _toast("Dialog primitive unavailable", "err");
      return;
    }
    var options = templates.map(function (t, idx) {
      var label = (t.name || t.title || t.id || "(untitled)");
      var meta = t.agreementType ? " — " + t.agreementType : "";
      return '<option value="' + idx + '">' + _esc(label) + _esc(meta) + '</option>';
    }).join("");
    var bodyHtml =
      '<div class="_bc_picker_form">' +
        '<p>' + templates.length + ' template' + (templates.length === 1 ? '' : 's') + ' available. ' +
        'Choose one to paste into the current Word document at the cursor.</p>' +
        '<div class="_bc_picker_row">' +
          '<label>Template</label>' +
          '<select id="_bc_pick_idx" size="' + Math.min(12, Math.max(5, templates.length)) + '">' + options + '</select>' +
        '</div>' +
        '<p style="font-size:11px;color:#64748b;margin-top:8px;">' +
          '💡 To export more than one, run this again after each — each export appends to the current doc.' +
        '</p>' +
      '</div>';

    showEliDialog({
      variant: "neutral",
      size: "wide",
      icon: "📄",
      title: "Pick a BD template to export",
      body: bodyHtml,
      buttons: [
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) { if (ov && ov.parentNode) ov.parentNode.removeChild(ov); },
        },
        {
          label: "Export selected",
          cls: "btn-action btn-primary",
          onclick: function (e, overlay) {
            var sel = document.getElementById("_bc_pick_idx");
            if (!sel || sel.value === "") { _toast("Pick a template first", "warn"); return false; }
            var t = templates[Number(sel.value)];
            if (!t) { _toast("Selection invalid", "err"); return false; }
            var label = (t.name || t.id || "(untitled)");
            var metaLines = [];
            if (t.agreementType) metaLines.push("Agreement type: " + t.agreementType);
            if (t.party) metaLines.push("Party: " + t.party);
            if (t.modifiedAt) metaLines.push("Last modified: " + new Date(t.modifiedAt).toLocaleString());
            var body = t.content;
            if (typeof body !== "string") {
              body = "[ERROR: template content is not a string (type=" + (typeof body) + "). " +
                "This usually means pako didn't load. Check Script Lab Libraries tab.]";
            }
            if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
            // Confirm destructive replace before writing — Word.js requires
            // InsertLocation.replace for OOXML packages, which wipes the
            // current doc. Same pattern admin_template_studio uses.
            if (eli.ui && typeof eli.ui.confirm === "function") {
              eli.ui.confirm({
                variant: "warning",
                icon: "⚠️",
                title: "Replace current document?",
                message: "Exporting \"" + _esc(label) + "\" will <b>replace everything in the current Word document</b> with the template content.<br><br>" +
                  "Open a blank document first if you want to keep your current doc untouched.",
                confirmLabel: "Replace and export",
                cancelLabel: "Cancel",
              }).then(function (ok) {
                if (!ok) return;
                _toast("⏳ Writing template to doc…", "info");
                _writeBdTemplateToDoc(label, metaLines, body)
                  .then(function () { _toast("✅ Exported \"" + label + "\" to current doc", "ok"); })
                  .catch(function (err) { _toast("Export failed: " + (err && err.message || "unknown"), "err"); });
              });
            } else {
              // No confirm primitive — proceed directly (still works).
              _toast("⏳ Writing template to doc…", "info");
              _writeBdTemplateToDoc(label, metaLines, body)
                .then(function () { _toast("✅ Exported \"" + label + "\" to current doc", "ok"); })
                .catch(function (err) { _toast("Export failed: " + (err && err.message || "unknown"), "err"); });
            }
          },
        },
      ],
    });
  }

  function _exportClauses() {
    _toast("⏳ Reading clause library…", "info");
    return eli.storage.getAll("bd_clauses").then(function (rows) {
      if (!rows || !rows.length) {
        _toast("No clauses found", "warn");
        return;
      }
      var paragraphs = [{ heading: "Total clauses: " + rows.length }];
      rows.forEach(function (c) {
        var label = c.name || c.id || "(untitled)";
        paragraphs.push({ heading: "── " + label + " ──" });
        if (c.topic) paragraphs.push("Topic: " + c.topic);
        if (c.tier) paragraphs.push("Tier: " + c.tier);
        if (c.text || c.body) {
          paragraphs.push("");
          paragraphs.push(c.text || c.body);
        }
        paragraphs.push("");
      });
      return _writeDocBlocks("ELI — Clause Library Export (" + rows.length + ")", paragraphs)
        .then(function () { _toast("✅ Exported " + rows.length + " clauses to current doc", "ok"); });
    }).catch(function (err) {
      _toast("Export failed: " + (err && err.message || "unknown"), "err");
    });
  }

  function _exportTeamGuidance() {
    _toast("⏳ Reading team guidance…", "info");
    return eli.storage.getAll("team_commentary").then(function (rows) {
      if (!rows || !rows.length) {
        _toast("No team guidance entries found", "warn");
        return;
      }
      var paragraphs = [{ heading: "Total entries: " + rows.length }];
      rows.forEach(function (g) {
        var label = (g.clause || g.id || "(untitled)") + " — " + (g.agreementType || "any");
        paragraphs.push({ heading: "── " + label + " ──" });
        if (g.author) paragraphs.push("Author: " + g.author);
        if (g.createdAt) paragraphs.push("When: " + new Date(g.createdAt).toLocaleString());
        if (g.body || g.text) {
          paragraphs.push("");
          paragraphs.push(g.body || g.text);
        }
        paragraphs.push("");
      });
      return _writeDocBlocks("ELI — Team Guidance Export (" + rows.length + ")", paragraphs)
        .then(function () { _toast("✅ Exported " + rows.length + " guidance entries to current doc", "ok"); });
    }).catch(function (err) {
      _toast("Export failed: " + (err && err.message || "unknown"), "err");
    });
  }

  function _exportPlaybooks() {
    _toast("⏳ Reading playbooks…", "info");
    return eli.storage.getAll("playbooks").then(function (rows) {
      if (!rows || !rows.length) {
        _toast("No playbooks found", "warn");
        return;
      }
      var paragraphs = [{ heading: "Total playbooks: " + rows.length }];
      rows.forEach(function (p) {
        paragraphs.push({ heading: "── " + (p.name || p.id || "(untitled)") + " ──" });
        if (p.agreementType) paragraphs.push("Agreement type: " + p.agreementType);
        if (p.rules && Array.isArray(p.rules)) {
          paragraphs.push("");
          paragraphs.push("Rules (" + p.rules.length + "):");
          p.rules.forEach(function (r, idx) {
            paragraphs.push("  " + (idx + 1) + ". " + (r.title || r.id || ""));
            if (r.description) paragraphs.push("     " + r.description);
          });
        }
        paragraphs.push("");
      });
      return _writeDocBlocks("ELI — Playbooks Export (" + rows.length + ")", paragraphs)
        .then(function () { _toast("✅ Exported " + rows.length + " playbooks to current doc", "ok"); });
    }).catch(function (err) {
      _toast("Export failed: " + (err && err.message || "unknown"), "err");
    });
  }

  // Full IDB dump — every store as a JSON blob, pasted into the doc.
  // Less useful for humans, more useful as a structured backup.
  function _exportAllJson() {
    _toast("⏳ Dumping all IDB stores…", "info");
    var stores = [
      "templates", "playbooks", "requesters", "bd_templates", "risk_rules",
      "trophies", "catalog", "prompts", "email_templates", "agreement_types",
      "loading_msgs", "cleaner_rules", "exec_brief_terms", "json_tools",
      "team_commentary", "bd_clauses",
    ];
    var dump = { exportedAt: new Date().toISOString(), stores: {} };
    return Promise.all(stores.map(function (s) {
      return eli.storage.getAll(s).then(function (rows) {
        dump.stores[s] = rows || [];
      }).catch(function (e) {
        dump.stores[s] = { error: e && e.message };
      });
    })).then(function () {
      var json = JSON.stringify(dump, null, 2);
      var paragraphs = [
        { heading: "JSON dump — " + stores.length + " stores" },
        "Paste this into a .json file and back it up somewhere safe.",
        "",
        json,
      ];
      return _writeDocBlocks("ELI — Full IDB Dump", paragraphs)
        .then(function () { _toast("✅ JSON dump pasted (" + (json.length / 1024).toFixed(1) + " KB)", "ok"); });
    }).catch(function (err) {
      _toast("Dump failed: " + (err && err.message || "unknown"), "err");
    });
  }

  var EXPORTS = {
    "export-bd-templates": _exportBdTemplates,
    "export-clauses":      _exportClauses,
    "export-team-guidance": _exportTeamGuidance,
    "export-playbooks":    _exportPlaybooks,
    "export-all-json":     _exportAllJson,
  };

  // ─── Tab orchestration ───────────────────────────────────────────
  function _renderTabbedView(activeTab) {
    var tabs = [
      { id: "how", label: "How ELI works" },
      { id: "continue", label: "Option 1: Continue" },
      { id: "winddown", label: "Option 2: Wind down + export" },
    ];
    var tabBar = tabs.map(function (t) {
      var isActive = t.id === activeTab;
      return '<button class="_bc_tab' + (isActive ? ' _bc_tab_active' : '') + '" data-bc-tab="' + t.id + '">' +
        _esc(t.label) + '</button>';
    }).join("");
    var body;
    if (activeTab === "how") body = _renderHowItWorks();
    else if (activeTab === "continue") body = _renderOption1();
    else body = _renderOption2();

    return '' +
      '<div class="_bc_root">' +
        '<div class="_bc_header">' +
          '<h1>📋 ELI — Business Continuity</h1>' +
          '<div class="_bc_header_sub">For whoever inherits ELI maintenance. Read each tab.</div>' +
        '</div>' +
        '<div class="_bc_tabs">' + tabBar + '</div>' +
        body +
      '</div>';
  }

  function _launch() {
    var out = window.eli.ui.claimOutput();
    var activeTab = "how";
    function _paint() {
      out.innerHTML = _renderTabbedView(activeTab);
      out.onclick = function (ev) {
        var t = ev.target;
        while (t && t !== out) {
          var tab = t.getAttribute && t.getAttribute("data-bc-tab");
          if (tab) { activeTab = tab; _paint(); return; }
          var act = t.getAttribute && t.getAttribute("data-bc-act");
          if (act && EXPORTS[act]) { EXPORTS[act](); return; }
          t = t.parentNode;
        }
      };
    }
    _paint();
    eli.log.event("tool", "business_continuity_loaded", {});
  }

  if (eli.register) {
    eli.register({
      tile: {
        app_business_continuity: eli.events && eli.events.guard
          ? eli.events.guard(function () { _launch(); }, "business_continuity.tile")
          : function () { _launch(); },
      },
    });
  }

  eli.log.event("tool", "business_continuity_initialized", {});
}

