/* tools/business_continuity/style.css
   Succession-guide app. Light palette in both themes (CLAUDE.md rule). */

._bc_root {
  font: 13px/1.5 'Inter', system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 16px;
  min-height: 100vh;
  box-sizing: border-box;
  /* 2026-05-23: kernel's .output-area is a flex column with transparent
     bg — without flex grow, the tool root sizes to content height and
     anything past that scrolls revealing the body's navy dashboard bg.
     Combine flex grow with display:block so children lay out normally. */
  flex: 1 0 auto;
}
/* Belt-and-suspenders: paint the output container behind us light too
   when this tool is the active surface. :has() is widely supported in
   modern Chromium / WebView2 / Edge / Safari 15.4+ used by Office. */
.beta-ui-active .output-area:has(> ._bc_root),
.output-area:has(> ._bc_root) {
  background: #f8fafc !important;
}

._bc_header {
  background: linear-gradient(135deg, #1e3a8a 0%, #1565c0 100%);
  color: #fff;
  padding: 16px 18px;
  margin-bottom: 14px;
  border-radius: 4px;
}
._bc_header h1 {
  margin: 0 0 4px 0;
  font: 700 18px/1.2 'Georgia', serif;
}
._bc_header_sub {
  font-size: 12px;
  color: #cbd5e1;
}

._bc_tabs {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid #cbd5e1;
  margin-bottom: 14px;
}
._bc_tab {
  font: 600 12px/1 'Inter', sans-serif;
  padding: 8px 14px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  border-bottom: none;
  border-radius: 3px 3px 0 0;
  color: #475569;
  cursor: pointer;
  margin-bottom: -2px;
}
._bc_tab:hover { background: #e2e8f0; }
._bc_tab_active {
  background: #fff;
  color: #0f172a;
  border-bottom: 2px solid #fff;
}

._bc_section {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #1565c0;
  padding: 16px 20px;
  border-radius: 0 4px 4px 0;
}
._bc_section h2 {
  margin: 0 0 12px 0;
  font: 700 16px/1.2 'Georgia', serif;
  color: #0f172a;
  border-bottom: 1px solid #e2e8f0;
  padding-bottom: 8px;
}
._bc_section h3 {
  margin: 16px 0 6px 0;
  font: 700 13px/1.2 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #475569;
}
._bc_section p {
  margin: 6px 0 10px 0;
}
._bc_section ul, ._bc_section ol {
  margin: 6px 0 12px 0;
  padding-left: 22px;
}
._bc_section li {
  margin-bottom: 4px;
}
._bc_section code {
  background: #f1f5f9;
  padding: 1px 5px;
  border-radius: 2px;
  font: 11.5px/1.4 'Monaco', monospace;
  color: #0d47a1;
}

._bc_table {
  width: 100%;
  border-collapse: collapse;
  margin: 8px 0 12px 0;
  font-size: 12px;
}
._bc_table th, ._bc_table td {
  border: 1px solid #cbd5e1;
  padding: 6px 8px;
  vertical-align: top;
  text-align: left;
}
._bc_table th {
  background: #f1f5f9;
  font-weight: 700;
  color: #475569;
}

._bc_export_grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 10px 0;
}
._bc_btn {
  font: 600 12px/1.3 'Inter', sans-serif;
  padding: 10px 14px;
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  border-bottom-width: 2px;
  color: #0f172a;
  cursor: pointer;
  border-radius: 3px;
  transition: filter 0.12s;
  text-align: left;
}
._bc_btn:hover { filter: brightness(0.97); }
._bc_btn_primary {
  background: linear-gradient(180deg, #1565c0 0%, #0d47a1 100%);
  border-color: #0d47a1;
  color: #fff;
}
._bc_btn_primary:hover { filter: brightness(1.08); }
._bc_btn_subtle {
  font-weight: 500;
  font-size: 11px;
  background: #f8fafc;
  color: #64748b;
  grid-column: 1 / -1;
}

._bc_picker_form {
  font: 13px/1.5 'Inter', system-ui, sans-serif;
}
._bc_picker_row {
  margin: 10px 0;
}
._bc_picker_row label {
  display: block;
  font: 700 11px/1.2 'Inter', sans-serif;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 4px;
}
._bc_picker_row select {
  width: 100%;
  font: 13px/1.4 'Inter', sans-serif;
  padding: 6px 8px;
  border: 1px solid #cbd5e1;
  border-radius: 3px;
  background: #fff;
  color: #0f172a;
  box-sizing: border-box;
}
._bc_picker_row select option {
  padding: 4px 6px;
}
